fn extract_rear_chars(l: &Vec<Vec<char>>) -> Vec<char> {
    l.iter()
        .map(|inner| *inner.last().unwrap()) // Get the last character of each inner vector
        .collect() // Collect the results into a new vector
}

fn main() {
    // Example usage
    let input = vec![
        vec!['a', 'b', 'c'],
        vec!['d', 'e'],
        vec!['f', 'g', 'h', 'i'],
    ];
    
    let result = extract_rear_chars(&input);
    println!("{:?}", result); // Output: ['c', 'e', 'i']
}